    <div class="hc-navigation-sidebar-actions"><button id="hc-navigation-locate" class="hc-navigation-primary" type="button">◎ ${esc(tr('My location'))}</button><button id="hc-navigation-save-current" type="button">＋ ${esc(tr('Save location'))}</button></div>
