function renderMapDiagnostics(){const el=$('s-map-diagnostics');if(!el)return;if(mapDiagnosticsError){el.classList.add('is-error');el.textContent=tr('Map cache diagnostics are unavailable: {error}',{error:mapDiagnosticsError});return}el.classList.remove('is-error');if(!mapDiagnostics){el.textContent=tr('Loading map cache diagnostics…');return}const providerState=(mapDiagnostics.providers||[]).map(p=>`${p.name||p.id}: ${!p.enabled?tr('disabled'):p.requiresApiKey&&!p.configured?tr('API key missing'):tr('ready')}`).join(' · ')||'—';el.innerHTML=`<div><strong>${esc(tr('Cache'))}</strong><span>${esc(tr('{count} tiles, {size}, {percent}% used',{count:mapDiagnostics.cacheEntryCount||0,size:formatBytes(mapDiagnostics.cacheBytes),percent:Number(mapDiagnostics.cacheUsagePercent||0).toFixed(2)}))}</span></div><div><strong>${esc(tr('Hit / miss today'))}</strong><span>${esc(String(mapDiagnostics.cacheHits||0)+' / '+String(mapDiagnostics.cacheMisses||0))}</span></div><div><strong>${esc(tr('External / saved requests'))}</strong><span>${esc(String(mapDiagnostics.externalRequests||0)+' / '+String(mapDiagnostics.savedExternalRequests||0))}</span></div><div><strong>${esc(tr('Providers'))}</strong><span>${esc(providerState)}</span></div><small>${esc(mapDiagnostics.canManage?tr('You can manage the global map cache settings.'):tr('Statistics are read-only; only an administrator can change global cache settings.'))}</small>${mapDiagnostics.canManage?`<div class="hc-navigation-map-key-offer"><label>${esc(tr('Offer a Mapy.com API key to Shared App Core'))}<input id="s-mapy-key" type="password" autocomplete="new-password" placeholder="Mapy.com API key"></label><button id="s-mapy-key-offer" type="button">${esc(tr('Validate and activate key'))}</button><small>${esc(tr('The key is validated and stored only by Shared App Core. Navigation never reads the active key back.'))}</small></div>`:''}`;if(mapDiagnostics.canManage)$('s-mapy-key-offer')?.addEventListener('click',()=>void offerMapyKey())}
