async function offerMapyKey(){const input=$('s-mapy-key'),button=$('s-mapy-key-offer');const key=input?.value?.trim()||'';if(!key){notifyWarning(tr('Enter a Mapy.com API key first.'));return}if(button)button.disabled=true;try{await core.maps.providers.offerKey({provider:'mapy',sourceApp:APP,key,activate:true});if(input)input.value='';notifySuccess(tr('The Mapy.com API key was validated and offered to Shared App Core.'));await refreshMapProviders();await loadMapDiagnostics();renderMap()}catch(e){notifyError(e instanceof Error?e.message:String(e))}finally{if(button)button.disabled=false}}
