function createCoreMapDriver(){const oListeners=new Map();const fEmit=sEvent=>(oListeners.get(sEvent)||new Set()).forEach(fn=>fn());return {getCenter:()=>({lat:state.lat,lon:state.lon}),getZoom:()=>state.zoom,getBounds:()=>{const oRect=map.getBoundingClientRect(),nScale=256*Math.pow(2,state.zoom),nCx=lng2x(state.lon,state.zoom)*256,nCy=lat2y(state.lat,state.zoom)*256;return {north:y2lat((nCy-oRect.height/2)/256,state.zoom),south:y2lat((nCy+oRect.height/2)/256,state.zoom),west:x2lng((nCx-oRect.width/2)/256,state.zoom),east:x2lng((nCx+oRect.width/2)/256,state.zoom)}},setView:(oCenter,nZoom)=>{fEmit('movestart');state.lat=oCenter.lat;state.lon=oCenter.lon;if(Number.isFinite(nZoom))state.zoom=Math.max(2,Math.min(19,Number(nZoom)));renderMap();fEmit('moveend')},zoomIn:()=>{fEmit('zoomstart');state.zoom=Math.min(layers[state.layer].max,state.zoom+1);renderMap();fEmit('zoomend')},zoomOut:()=>{fEmit('zoomstart');state.zoom=Math.max(2,state.zoom-1);renderMap();fEmit('zoomend')},invalidateSize:()=>renderMap(),on:(sEvent,fn)=>{const oSet=oListeners.get(sEvent)||new Set();oSet.add(fn);oListeners.set(sEvent,oSet)},off:(sEvent,fn)=>oListeners.get(sEvent)?.delete(fn),destroy:()=>oListeners.clear()}}
